-- Reviewed senior batch 020; all images remotely verified.
begin;
do $guard$ declare batch_content jsonb := $senior_content$[{"source_id":4531,"word":"voyage","meaning":"航行","example":"The research voyage took the scientists along the northern coast.","example_zh":"研究航行帶科學家沿北方海岸前進。","original_meaning":"航行","original_example":"A long voyage.","original_example_zh":"一趟漫長的航程。"},{"source_id":4532,"word":"vulgar","meaning":"粗俗的","example":"The teacher asked the actor to replace the vulgar joke with something kinder.","example_zh":"老師請演員把粗俗笑話改成更友善的內容。","original_meaning":"粗俗的","original_example":"Vulgar language.","original_example_zh":"粗俗的語言。"},{"source_id":4533,"word":"waiver","meaning":"放棄；豁免","example":"The school approved a waiver of the competition fee.","example_zh":"學校批准豁免比賽費用。","original_meaning":"放棄","original_example":"Sign a waiver.","original_example_zh":"簽署免責聲明。"},{"source_id":4534,"word":"warfare","meaning":"戰爭","example":"The history exhibit examined the effects of warfare on ordinary families.","example_zh":"歷史展覽探討戰爭對一般家庭的影響。","original_meaning":"戰爭","original_example":"Chemical warfare.","original_example_zh":"化學戰。"},{"source_id":4535,"word":"warranty","meaning":"保固","example":"The shop explained the camera's warranty before the purchase.","example_zh":"購買前，商店說明相機保固。","original_meaning":"保固","original_example":"A product warranty.","original_example_zh":"產品保固。"},{"source_id":4536,"word":"waterfall","meaning":"瀑布","example":"The trail led to a viewpoint beside the waterfall.","example_zh":"步道通往瀑布旁的觀景點。","original_meaning":"瀑布","original_example":"A beautiful waterfall.","original_example_zh":"一座美麗的瀑布。"},{"source_id":4537,"word":"wheelchair","meaning":"輪椅","example":"The wide path allowed her wheelchair to reach the garden easily.","example_zh":"寬敞步道讓她的輪椅輕鬆抵達花園。","original_meaning":"輪椅","original_example":"Use a wheelchair.","original_example_zh":"使用輪椅。"},{"source_id":4538,"word":"whisper","meaning":"低語","example":"She began to whisper so that the readers would not be disturbed.","example_zh":"她開始低聲說話，避免打擾閱讀者。","original_meaning":"低語","original_example":"She whispered softly.","original_example_zh":"她輕聲低語。"},{"source_id":4539,"word":"windmill","meaning":"風車","example":"The old windmill stood above the fields.","example_zh":"老風車矗立在田野上方。","original_meaning":"風車","original_example":"A Dutch windmill.","original_example_zh":"一座荷蘭風車。"},{"source_id":4540,"word":"witchcraft","meaning":"巫術","example":"The folk tale described witchcraft as the source of the glowing garden.","example_zh":"民間故事把發光花園歸因於巫術。","original_meaning":"巫術","original_example":"Accused of witchcraft.","original_example_zh":"被指控施行巫術。"},{"source_id":4541,"word":"withdrawal","meaning":"撤回","example":"The withdrawal of the proposal allowed more time for discussion.","example_zh":"撤回提案，讓大家有更多討論時間。","original_meaning":"撤回","original_example":"A military withdrawal.","original_example_zh":"軍事撤軍。"},{"source_id":4542,"word":"wrath","meaning":"憤怒","example":"The story's ruler showed wrath when the plan failed.","example_zh":"故事中的統治者在計畫失敗時大發雷霆。","original_meaning":"憤怒","original_example":"Incur wrath.","original_example_zh":"招致怒火。"},{"source_id":4543,"word":"wreckage","meaning":"殘骸","example":"The museum preserved wreckage from an old fishing boat.","example_zh":"博物館保存一艘老漁船的殘骸。","original_meaning":"殘骸","original_example":"Search the wreckage.","original_example_zh":"搜查殘骸。"},{"source_id":4544,"word":"undertake","meaning":"承擔","example":"The club agreed to undertake the restoration of the school garden.","example_zh":"社團同意承擔修復校園花園的工作。","original_meaning":"承擔","original_example":"Undertake a project.","original_example_zh":"承接一個專案。"},{"source_id":4545,"word":"unilateral","meaning":"單邊的","example":"The unilateral decision surprised the other partner.","example_zh":"單方面的決定讓另一位合作夥伴驚訝。","original_meaning":"單邊的","original_example":"A unilateral decision.","original_example_zh":"單方面決定。"},{"source_id":4546,"word":"uranium","meaning":"鈾","example":"The museum displayed a uranium mineral inside a sealed protective case.","example_zh":"博物館在密閉防護櫃中展示含鈾礦物。","original_meaning":"鈾","original_example":"Enrich uranium.","original_example_zh":"鈾濃縮。"},{"source_id":4547,"word":"utensil","meaning":"器具","example":"The wooden spoon was the most useful utensil in the cooking lesson.","example_zh":"木湯匙是烹飪課裡最實用的器具。","original_meaning":"器具","original_example":"Kitchen utensils.","original_example_zh":"廚房用具。"},{"source_id":4548,"word":"utopia","meaning":"烏托邦","example":"The novel imagined a utopia where every community had a library.","example_zh":"小說想像每個社區都有圖書館的烏托邦。","original_meaning":"烏托邦","original_example":"An ideal utopia.","original_example_zh":"理想的烏托邦。"},{"source_id":4549,"word":"adhere","meaning":"遵守","example":"All teams must adhere to the safety rules in the workshop.","example_zh":"所有隊伍在工坊都必須遵守安全規則。","original_meaning":"遵守","original_example":"Adhere to the rules.","original_example_zh":"遵守規則。"},{"source_id":4550,"word":"advent","meaning":"來臨","example":"The advent of the railway changed the village's daily life.","example_zh":"鐵路到來改變村莊日常生活。","original_meaning":"來臨","original_example":"The advent of technology.","original_example_zh":"科技的出現。"},{"source_id":4551,"word":"affirm","meaning":"肯定","example":"The teacher's response helped affirm the student's confidence.","example_zh":"老師的回應幫助肯定學生的信心。","original_meaning":"肯定","original_example":"Affirm your belief.","original_example_zh":"堅定你的信念。"},{"source_id":4552,"word":"agenda","meaning":"議程","example":"The meeting's agenda included plans for the reading festival.","example_zh":"會議議程包括閱讀節規劃。","original_meaning":"議程","original_example":"Set the agenda.","original_example_zh":"制定議程。"},{"source_id":4553,"word":"aisle","meaning":"走道","example":"The visitors kept the aisle clear during the performance.","example_zh":"演出期間，訪客讓走道保持暢通。","original_meaning":"走道","original_example":"Walk down the aisle.","original_example_zh":"走過紅毯。"},{"source_id":4554,"word":"alienate","meaning":"疏遠","example":"Ignoring her ideas could alienate a valuable team member.","example_zh":"忽視她的想法，可能疏遠一位重要隊員。","original_meaning":"疏遠","original_example":"Alienate your friends.","original_example_zh":"疏遠朋友。"},{"source_id":4555,"word":"altruistic","meaning":"利他的","example":"The altruistic volunteers spent the weekend repairing community benches.","example_zh":"利他的志工花週末修理社區長椅。","original_meaning":"利他的","original_example":"An altruistic gesture.","original_example_zh":"一個利他的舉動。"},{"source_id":4556,"word":"amend","meaning":"修訂","example":"The students will amend the plan to include a wider path.","example_zh":"學生將修訂計畫，加入更寬的步道。","original_meaning":"修訂","original_example":"Amend the constitution.","original_example_zh":"修訂憲法。"},{"source_id":4557,"word":"antagonize","meaning":"對抗；惹惱","example":"His repeated interruptions began to antagonize the other speakers.","example_zh":"他反覆打斷發言，開始惹惱其他講者。","original_meaning":"對抗","original_example":"Do not antagonize him.","original_example_zh":"不要激怒他。"},{"source_id":4558,"word":"ardent","meaning":"熱烈的","example":"The ardent reader visited the library every afternoon.","example_zh":"那位熱愛閱讀的人每天下午都去圖書館。","original_meaning":"熱烈的","original_example":"An ardent fan.","original_example_zh":"一位狂熱的粉絲。"},{"source_id":4559,"word":"astute","meaning":"精明的","example":"The astute designer noticed a weakness in the bridge model.","example_zh":"精明的設計師注意到模型橋的一處弱點。","original_meaning":"精明的","original_example":"An astute observer.","original_example_zh":"一位敏銳的觀察者。"},{"source_id":4560,"word":"austere","meaning":"嚴峻的；樸素的","example":"The austere room contained only a desk, a chair, and a lamp.","example_zh":"樸素房間只擺一張桌、一把椅子與一盞燈。","original_meaning":"嚴峻的","original_example":"An austere environment.","original_example_zh":"一個嚴肅的環境。"},{"source_id":4561,"word":"baffle","meaning":"使困惑","example":"The unfamiliar mechanism continued to baffle the students.","example_zh":"陌生機構仍讓學生困惑。","original_meaning":"使困惑","original_example":"The question baffled me.","original_example_zh":"這個問題讓我困惑不已。"},{"source_id":4562,"word":"barren","meaning":"荒蕪的","example":"The barren hillside had almost no vegetation.","example_zh":"荒蕪山坡幾乎沒有植被。","original_meaning":"荒蕪的","original_example":"Barren wasteland.","original_example_zh":"荒蕪的荒地。"},{"source_id":4563,"word":"besiege","meaning":"圍攻","example":"The model showed how an army could besiege the old city.","example_zh":"模型展示軍隊如何圍攻古城。","original_meaning":"圍攻","original_example":"Besiege the castle.","original_example_zh":"圍攻城堡。"},{"source_id":4564,"word":"bewilder","meaning":"使迷惑","example":"The maze's many turns could bewilder a first-time visitor.","example_zh":"迷宮眾多轉彎，可能讓初次訪客迷惑。","original_meaning":"使迷惑","original_example":"The maze bewildered us.","original_example_zh":"迷宮讓我們感到困惑。"},{"source_id":4565,"word":"bland","meaning":"平淡的","example":"The plain soup tasted bland until the cook added herbs.","example_zh":"清湯原本味道平淡，廚師加香草後才有滋味。","original_meaning":"平淡的","original_example":"Bland food.","original_example_zh":"寡淡的食物。"},{"source_id":4566,"word":"blatant","meaning":"公然的","example":"The blatant disregard for the queue upset the waiting visitors.","example_zh":"公然無視排隊秩序，讓等候訪客不悅。","original_meaning":"公然的","original_example":"A blatant lie.","original_example_zh":"一個赤裸裸的謊言。"},{"source_id":4567,"word":"bleak","meaning":"蕭條的","example":"The empty station looked bleak in the winter rain.","example_zh":"冬雨中的空車站顯得蕭條。","original_meaning":"蕭條的","original_example":"A bleak outlook.","original_example_zh":"前景黯淡。"},{"source_id":4568,"word":"blight","meaning":"枯萎病","example":"The farmer examined leaves damaged by blight.","example_zh":"農民檢查受到枯萎病損害的葉片。","original_meaning":"枯萎病","original_example":"A crop blight.","original_example_zh":"作物瘟疫。"},{"source_id":4569,"word":"bliss","meaning":"極樂","example":"Reading beneath the quiet trees gave her a feeling of bliss.","example_zh":"在寧靜樹下閱讀，讓她感到無比幸福。","original_meaning":"極樂","original_example":"Ignorance is bliss.","original_example_zh":"無知即幸福。"},{"source_id":4570,"word":"boon","meaning":"恩惠；益處","example":"The new footbridge was a boon to residents who walked to school.","example_zh":"新人行橋為步行上學的居民帶來便利。","original_meaning":"恩惠","original_example":"A boon for business.","original_example_zh":"對商業的福音。"},{"source_id":4571,"word":"brash","meaning":"莽撞的","example":"The brash speaker interrupted before hearing the full proposal.","example_zh":"那位莽撞講者未聽完整提案就插話。","original_meaning":"莽撞的","original_example":"A brash young man.","original_example_zh":"一個莽撞的年輕人。"},{"source_id":4572,"word":"brevity","meaning":"簡短","example":"The speech's brevity left more time for questions.","example_zh":"演說簡短，因此留下更多提問時間。","original_meaning":"簡短","original_example":"Brevity is valued.","original_example_zh":"簡潔是美德。"},{"source_id":4573,"word":"broach","meaning":"提出","example":"She decided to broach the subject of sharing the rehearsal room.","example_zh":"她決定提出共用排練室的議題。","original_meaning":"提出","original_example":"Broach the subject.","original_example_zh":"提起這個話題。"},{"source_id":4574,"word":"brusque","meaning":"無禮的","example":"His brusque reply made the new volunteer feel unwelcome.","example_zh":"他生硬無禮的回覆讓新志工覺得不受歡迎。","original_meaning":"無禮的","original_example":"A brusque reply.","original_example_zh":"一句生硬的回答。"},{"source_id":4575,"word":"callous","meaning":"冷酷的","example":"The story criticized the callous landlord who ignored the tenants' needs.","example_zh":"故事批評漠視房客需要的冷酷房東。","original_meaning":"冷酷的","original_example":"A callous attitude.","original_example_zh":"冷漠的態度。"},{"source_id":4576,"word":"candor","meaning":"坦率","example":"Her candor helped the team understand why the first design failed.","example_zh":"她坦率說明，幫團隊理解第一版設計為何失敗。","original_meaning":"坦率","original_example":"Speak with candor.","original_example_zh":"坦率地說話。"},{"source_id":4577,"word":"caption","meaning":"標題；圖片說明","example":"The photograph's caption explained where it was taken.","example_zh":"照片下的說明交代拍攝地點。","original_meaning":"標題","original_example":"Add a caption.","original_example_zh":"添加圖說。"},{"source_id":4578,"word":"captivate","meaning":"迷住","example":"The moving performance could captivate the entire audience.","example_zh":"動人演出能迷住全場觀眾。","original_meaning":"迷住","original_example":"Captivate the audience.","original_example_zh":"吸引觀眾的注意力。"},{"source_id":4579,"word":"cede","meaning":"割讓","example":"The historical agreement required the kingdom to cede a small territory.","example_zh":"歷史協議要求王國割讓一小塊領土。","original_meaning":"割讓","original_example":"Cede control.","original_example_zh":"交出控制權。"},{"source_id":4580,"word":"censure","meaning":"譴責","example":"The council voted to censure the official for concealing the report.","example_zh":"議會表決譴責那位隱匿報告的官員。","original_meaning":"譴責","original_example":"Censure the official.","original_example_zh":"譴責該官員。"},{"source_id":4581,"word":"cipher","meaning":"密碼","example":"The museum displayed a cipher used in old diplomatic messages.","example_zh":"博物館展示古外交訊息使用的密碼。","original_meaning":"密碼","original_example":"Break the cipher.","original_example_zh":"破解密碼。"},{"source_id":4582,"word":"circumscribe","meaning":"限制","example":"The rules circumscribe the areas where visitors may walk.","example_zh":"規則限制訪客可以行走的範圍。","original_meaning":"限制","original_example":"Circumscribe power.","original_example_zh":"限制權力。"},{"source_id":4583,"word":"clamor","meaning":"喧嚷","example":"The excited fans began to clamor for one more song.","example_zh":"興奮樂迷喧嚷著要求再唱一首。","original_meaning":"喧嚷","original_example":"Clamor for attention.","original_example_zh":"爭相吸引注意。"},{"source_id":4584,"word":"cognizant","meaning":"認知到的","example":"The guide was cognizant of the weather's sudden changes.","example_zh":"嚮導注意到天氣突然變化。","original_meaning":"認知到的","original_example":"Cognizant of the risks.","original_example_zh":"意識到風險。"},{"source_id":4585,"word":"colloquial","meaning":"口語的","example":"The dialogue used colloquial language to sound natural.","example_zh":"對話使用口語，讓語氣自然。","original_meaning":"口語的","original_example":"Colloquial language.","original_example_zh":"口語。"},{"source_id":4586,"word":"commensurate","meaning":"相稱的","example":"The prize was commensurate with the difficulty of the challenge.","example_zh":"獎項與挑戰的難度相稱。","original_meaning":"相稱的","original_example":"Salary commensurate with experience.","original_example_zh":"薪資與經驗相稱。"},{"source_id":4587,"word":"compelling","meaning":"令人信服的","example":"The photographs provided compelling evidence of the bridge's damage.","example_zh":"照片提供令人信服的橋梁受損證據。","original_meaning":"令人信服的","original_example":"A compelling argument.","original_example_zh":"一個極具說服力的論點。"},{"source_id":4588,"word":"complacent","meaning":"自滿的","example":"The complacent team stopped checking its work after an early success.","example_zh":"團隊早早成功後自滿，不再檢查作品。","original_meaning":"自滿的","original_example":"Do not be complacent.","original_example_zh":"不要自滿。"},{"source_id":4589,"word":"concur","meaning":"同意","example":"The two judges concur on which design is safest.","example_zh":"兩位評審同意哪個設計最安全。","original_meaning":"同意","original_example":"I concur.","original_example_zh":"我贊同。"},{"source_id":4590,"word":"condone","meaning":"容忍；縱容","example":"The teacher refused to condone cheating in the competition.","example_zh":"老師拒絕縱容比賽作弊。","original_meaning":"容忍","original_example":"Cannot condone violence.","original_example_zh":"無法容忍暴力。"},{"source_id":4591,"word":"congenial","meaning":"友好的","example":"The congenial host made every visitor feel welcome.","example_zh":"友善主人讓每位訪客都感到受歡迎。","original_meaning":"友好的","original_example":"A congenial atmosphere.","original_example_zh":"融洽的氛圍。"},{"source_id":4592,"word":"conjecture","meaning":"推測","example":"Her explanation remained a conjecture until the test was complete.","example_zh":"測試完成前，她的解釋仍是推測。","original_meaning":"推測","original_example":"Mere conjecture.","original_example_zh":"純屬臆測。"},{"source_id":4593,"word":"connive","meaning":"密謀","example":"The story's rivals connived to secure an unfair result.","example_zh":"故事中的對手密謀取得不公平結果。","original_meaning":"密謀","original_example":"Connive against the boss.","original_example_zh":"串通對抗老闆。"},{"source_id":4594,"word":"consecrate","meaning":"奉獻；祝聖","example":"The community gathered to consecrate the new chapel.","example_zh":"社區聚集參加新小教堂的祝聖儀式。","original_meaning":"奉獻","original_example":"Consecrate the church.","original_example_zh":"為教堂舉行祝聖儀式。"},{"source_id":4595,"word":"consolidate","meaning":"鞏固；整合","example":"The library will consolidate several small collections in one room.","example_zh":"圖書館將把數個小型收藏整合於一個房間。","original_meaning":"鞏固","original_example":"Consolidate gains.","original_example_zh":"鞏固成果。"},{"source_id":4596,"word":"conspire","meaning":"密謀","example":"The fictional ministers began to conspire against the ruler.","example_zh":"虛構大臣開始密謀反對統治者。","original_meaning":"密謀","original_example":"Conspire against the king.","original_example_zh":"密謀對抗國王。"},{"source_id":4597,"word":"constrain","meaning":"約束","example":"The narrow doorway could constrain the size of the model we carried.","example_zh":"狹窄門口可能限制我們搬運模型的尺寸。","original_meaning":"約束","original_example":"Constrained by budget.","original_example_zh":"受預算限制。"},{"source_id":4598,"word":"contagion","meaning":"傳染","example":"The exhibit traced how researchers studied contagion.","example_zh":"展覽追溯研究者如何探究傳染。","original_meaning":"傳染","original_example":"Stop the contagion.","original_example_zh":"阻止疫情蔓延。"},{"source_id":4599,"word":"contrite","meaning":"悔恨的","example":"The contrite student apologized for breaking the shared model.","example_zh":"懊悔的學生為弄壞共用模型道歉。","original_meaning":"悔恨的","original_example":"A contrite apology.","original_example_zh":"懺悔的道歉。"},{"source_id":4600,"word":"copious","meaning":"豐富的","example":"She took copious notes during the museum visit.","example_zh":"參觀博物館時，她做了豐富筆記。","original_meaning":"豐富的","original_example":"Copious notes.","original_example_zh":"詳盡的筆記。"},{"source_id":4601,"word":"cumulative","meaning":"累積的","example":"The cumulative effect of many small repairs restored the old library.","example_zh":"許多小修繕的累積效果，使老圖書館煥然一新。","original_meaning":"累積的","original_example":"A cumulative effect.","original_example_zh":"累積效應。"},{"source_id":4602,"word":"daunting","meaning":"令人怯步的","example":"The huge pile of unsorted books looked daunting at first.","example_zh":"大量未分類書籍，一開始看起來令人怯步。","original_meaning":"令人怯步的","original_example":"A daunting task.","original_example_zh":"一項艱鉅的任務。"},{"source_id":4603,"word":"debilitate","meaning":"使衰弱","example":"Long droughts can debilitate young trees.","example_zh":"長期乾旱會使幼樹衰弱。","original_meaning":"使衰弱","original_example":"Debilitated by illness.","original_example_zh":"因病而虛弱。"},{"source_id":4604,"word":"decadent","meaning":"頹廢的；奢靡的","example":"The decadent court spent lavishly while neglecting the village roads.","example_zh":"奢靡宮廷大肆花費，卻忽略村莊道路。","original_meaning":"頹廢的","original_example":"Decadent luxury.","original_example_zh":"奢靡的享樂。"},{"source_id":4605,"word":"decimate","meaning":"大量毀滅","example":"The violent storm could decimate the old orchard.","example_zh":"強烈風暴可能大量摧毀老果園。","original_meaning":"大量毀滅","original_example":"The plague decimated the population.","original_example_zh":"瘟疫使人口銳減。"},{"source_id":4606,"word":"defiance","meaning":"反抗","example":"Her quiet defiance showed when she refused to accept the unfair rule.","example_zh":"她拒絕接受不公平規則，展現沉靜反抗。","original_meaning":"反抗","original_example":"In defiance of the law.","original_example_zh":"公然違反法律。"},{"source_id":4607,"word":"deft","meaning":"靈巧的","example":"The deft craftsperson fitted the tiny wooden pieces together.","example_zh":"靈巧工匠把微小木零件接合。","original_meaning":"靈巧的","original_example":"A deft touch.","original_example_zh":"嫻熟的手法。"},{"source_id":4608,"word":"defunct","meaning":"已廢除的；停止運作的","example":"The defunct factory became an industrial museum.","example_zh":"停用工廠改成工業博物館。","original_meaning":"已廢除的","original_example":"A defunct company.","original_example_zh":"一家倒閉的公司。"},{"source_id":4609,"word":"degenerate","meaning":"退化","example":"Without maintenance, the tidy garden could degenerate into a tangle of weeds.","example_zh":"若缺乏維護，整齊花園可能退化成雜草叢。","original_meaning":"退化","original_example":"The situation degenerated.","original_example_zh":"局勢惡化。"},{"source_id":4610,"word":"delineate","meaning":"描繪","example":"The architect used a sketch to delineate the garden's main paths.","example_zh":"建築師用草圖描繪花園主要步道。","original_meaning":"描繪","original_example":"Delineate the boundaries.","original_example_zh":"劃定邊界。"},{"source_id":4611,"word":"demise","meaning":"滅亡；衰亡","example":"The book traced the demise of the old trading company.","example_zh":"書中追溯老貿易公司的衰亡。","original_meaning":"滅亡","original_example":"The demise of the empire.","original_example_zh":"帝國的覆滅。"},{"source_id":4612,"word":"deride","meaning":"嘲笑","example":"The counselor reminded students not to deride someone for making a mistake.","example_zh":"輔導員提醒學生，不要因別人犯錯而嘲笑。","original_meaning":"嘲笑","original_example":"Deride his efforts.","original_example_zh":"嘲笑他的努力。"},{"source_id":4613,"word":"despot","meaning":"暴君","example":"The tale described a despot who ignored the villagers' needs.","example_zh":"故事描寫漠視村民需要的暴君。","original_meaning":"暴君","original_example":"A ruthless despot.","original_example_zh":"一個殘忍的暴君。"},{"source_id":4614,"word":"detriment","meaning":"損害","example":"The leaking roof was a detriment to the old library's books.","example_zh":"漏雨屋頂損害老圖書館藏書。","original_meaning":"損害","original_example":"To the detriment of health.","original_example_zh":"對健康有害。"},{"source_id":4615,"word":"deviate","meaning":"偏離","example":"The hikers did not deviate from the marked trail.","example_zh":"健行者沒有偏離指定步道。","original_meaning":"偏離","original_example":"Deviate from the norm.","original_example_zh":"偏離常規。"},{"source_id":4616,"word":"devout","meaning":"虔誠的","example":"The devout visitors paused quietly inside the shrine.","example_zh":"虔誠訪客在神殿內安靜停留。","original_meaning":"虔誠的","original_example":"A devout believer.","original_example_zh":"一位虔誠的信徒。"},{"source_id":4617,"word":"diffuse","meaning":"擴散","example":"The blue dye began to diffuse through the water.","example_zh":"藍色染料開始在水中擴散。","original_meaning":"擴散","original_example":"Diffuse the tension.","original_example_zh":"緩解緊張。"},{"source_id":4618,"word":"dilapidated","meaning":"破舊的","example":"The dilapidated shed had broken boards and a sagging roof.","example_zh":"破舊棚屋有斷板與下垂屋頂。","original_meaning":"破舊的","original_example":"A dilapidated house.","original_example_zh":"一間破舊的房子。"},{"source_id":4619,"word":"dire","meaning":"可怕的；嚴重的","example":"The village faced a dire shortage of clean water.","example_zh":"村莊面臨嚴重缺乏乾淨飲水的困境。","original_meaning":"可怕的","original_example":"Dire consequences.","original_example_zh":"嚴重的後果。"},{"source_id":4620,"word":"disdain","meaning":"鄙視","example":"His disdain for careless workmanship showed in his frown.","example_zh":"他皺眉，流露對粗糙工藝的鄙視。","original_meaning":"鄙視","original_example":"Look with disdain.","original_example_zh":"以輕蔑的目光注視。"},{"source_id":4621,"word":"dismal","meaning":"慘淡的","example":"The abandoned station looked dismal beneath the grey sky.","example_zh":"灰天下廢棄車站顯得慘淡。","original_meaning":"慘淡的","original_example":"Dismal performance.","original_example_zh":"表現慘淡。"},{"source_id":4622,"word":"dismay","meaning":"沮喪","example":"The broken model filled the students with dismay.","example_zh":"模型壞掉，讓學生十分沮喪。","original_meaning":"沮喪","original_example":"To my dismay.","original_example_zh":"令我沮喪的是。"},{"source_id":4623,"word":"disparage","meaning":"貶低","example":"The mentor asked the group not to disparage a beginner's work.","example_zh":"導師請小組不要貶低新手作品。","original_meaning":"貶低","original_example":"Disparage his work.","original_example_zh":"貶低他的作品。"},{"source_id":4624,"word":"dispatch","meaning":"派遣","example":"The coordinator will dispatch a repair team to the village.","example_zh":"協調員將派遣維修隊前往村莊。","original_meaning":"派遣","original_example":"Dispatch a team.","original_example_zh":"派遣一支隊伍。"},{"source_id":4625,"word":"dispel","meaning":"消除","example":"The clear demonstration helped dispel our doubts about the design.","example_zh":"清楚示範幫助消除我們對設計的疑慮。","original_meaning":"消除","original_example":"Dispel rumors.","original_example_zh":"駁斥謠言。"},{"source_id":4626,"word":"disperse","meaning":"散開","example":"The visitors began to disperse after the concert.","example_zh":"音樂會後，訪客開始散去。","original_meaning":"散開","original_example":"The crowd dispersed.","original_example_zh":"人群散去。"},{"source_id":4627,"word":"dissent","meaning":"異議","example":"The meeting allowed room for respectful dissent.","example_zh":"會議容許尊重彼此的異議。","original_meaning":"異議","original_example":"Voice dissent.","original_example_zh":"表達異議。"},{"source_id":4628,"word":"dissipate","meaning":"消散","example":"The morning mist began to dissipate as the sun rose.","example_zh":"太陽升起後，晨霧開始消散。","original_meaning":"消散","original_example":"The fog dissipated.","original_example_zh":"霧氣消散了。"},{"source_id":4629,"word":"divert","meaning":"轉移","example":"The workers will divert traffic around the damaged bridge.","example_zh":"工人將引導交通繞過受損橋梁。","original_meaning":"轉移","original_example":"Divert attention.","original_example_zh":"轉移注意力。"},{"source_id":4630,"word":"divulge","meaning":"洩漏","example":"The guide would not divulge private details from the donated letters.","example_zh":"導覽員不願洩漏捐贈信件裡的私人細節。","original_meaning":"洩漏","original_example":"Divulge a secret.","original_example_zh":"洩露秘密。"}]$senior_content$::jsonb; begin
perform 1 from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' for update of w;
if (select count(*) from public.word_bank w join jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) on w.id=c.source_id and w.word=c.word where w.level='senior' and ((w.meaning,w.example,w.example_zh) is not distinct from (c.original_meaning,c.original_example,c.original_example_zh) or (w.meaning,w.example,w.example_zh) is not distinct from (c.meaning,c.example,c.example_zh))) <> 100 then raise exception 'Senior source rows changed; refusing overwrite'; end if;
update public.word_bank w set meaning=c.meaning,example=c.example,example_zh=c.example_zh from jsonb_to_recordset(batch_content) as c(source_id bigint,word text,meaning text,example text,example_zh text,original_meaning text,original_example text,original_example_zh text) where w.id=c.source_id and w.level='senior' and w.word=c.word;
end $guard$;
insert into public.word_illustrations(id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version) select id,level,word,sort_order,sense,alt_zh,example,example_zh,image_url,local_path,style,version from jsonb_to_recordset($senior_rows$[{"id":"senior-voyage-01-v1","level":"senior","word":"voyage","sort_order":1,"sense":"航行","alt_zh":"成年海洋研究員穿救生衣在平穩民用研究船甲板觀察海岸，高中訪客安全陪同。","example":"The research voyage took the scientists along the northern coast.","example_zh":"研究航行帶科學家沿北方海岸前進。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/voyage-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-vulgar-01-v1","level":"senior","word":"vulgar","sort_order":1,"sense":"粗俗的","alt_zh":"高中劇團排練時，成年老師溫和提醒演員修改不合宜台詞，無實際粗俗文字。","example":"The teacher asked the actor to replace the vulgar joke with something kinder.","example_zh":"老師請演員把粗俗笑話改成更友善的內容。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/vulgar-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-waiver-01-v1","level":"senior","word":"waiver","sort_order":1,"sense":"放棄；豁免","alt_zh":"成年行政人員在安靜辦公室向高中參賽者交付費用豁免文件，無數字。","example":"The school approved a waiver of the competition fee.","example_zh":"學校批准豁免比賽費用。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/waiver-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-warfare-01-v1","level":"senior","word":"warfare","sort_order":1,"sense":"戰爭","alt_zh":"高中生在和平博物館觀看歷史家庭行李與受損空屋照片，無戰鬥傷者。","example":"The history exhibit examined the effects of warfare on ordinary families.","example_zh":"歷史展覽探討戰爭對一般家庭的影響。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/warfare-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-warranty-01-v1","level":"senior","word":"warranty","sort_order":1,"sense":"保固","alt_zh":"成年相機店員向成年顧客展示保固文件與安全放在桌上的相機，無品牌文字。","example":"The shop explained the camera's warranty before the purchase.","example_zh":"購買前，商店說明相機保固。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/warranty-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-waterfall-01-v1","level":"senior","word":"waterfall","sort_order":1,"sense":"瀑布","alt_zh":"成年嚮導與高中生從穩固有護欄觀景臺欣賞壯麗瀑布。","example":"The trail led to a viewpoint beside the waterfall.","example_zh":"步道通往瀑布旁的觀景點。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/waterfall-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-wheelchair-01-v1","level":"senior","word":"wheelchair","sort_order":1,"sense":"輪椅","alt_zh":"成年輪椅使用者與高中朋友平等同行，沿平緩寬敞步道進入公園花園。","example":"The wide path allowed her wheelchair to reach the garden easily.","example_zh":"寬敞步道讓她的輪椅輕鬆抵達花園。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/wheelchair-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-whisper-01-v1","level":"senior","word":"whisper","sort_order":1,"sense":"低語","alt_zh":"高中女生在安靜圖書館靠近同學輕聲交談，周圍讀者專注閱讀。","example":"She began to whisper so that the readers would not be disturbed.","example_zh":"她開始低聲說話，避免打擾閱讀者。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/whisper-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-windmill-01-v1","level":"senior","word":"windmill","sort_order":1,"sense":"風車","alt_zh":"高中訪客與成年導覽員從安全小徑欣賞歷史木製風車與開闊農田。","example":"The old windmill stood above the fields.","example_zh":"老風車矗立在田野上方。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/windmill-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-witchcraft-01-v1","level":"senior","word":"witchcraft","sort_order":1,"sense":"巫術","alt_zh":"虛構童話中穿完整長袍的成年魔法角色站在柔和發光花園旁，氣氛夢幻友善，無危害儀式。","example":"The folk tale described witchcraft as the source of the glowing garden.","example_zh":"民間故事把發光花園歸因於巫術。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/witchcraft-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-withdrawal-01-v1","level":"senior","word":"withdrawal","sort_order":1,"sense":"撤回","alt_zh":"高中學生會代表在成年老師旁把提案文件收回，圓桌同學繼續平靜討論。","example":"The withdrawal of the proposal allowed more time for discussion.","example_zh":"撤回提案，讓大家有更多討論時間。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/withdrawal-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-wrath-01-v1","level":"senior","word":"wrath","sort_order":1,"sense":"憤怒","alt_zh":"高中生閱讀虛構歷史故事，插畫中成年統治者皺眉生氣、官員安靜聆聽，無傷害。","example":"The story's ruler showed wrath when the plan failed.","example_zh":"故事中的統治者在計畫失敗時大發雷霆。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/wrath-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-wreckage-01-v1","level":"senior","word":"wreckage","sort_order":1,"sense":"殘骸","alt_zh":"高中訪客在海事博物館觀看保存的破損民用木船船體，無事故傷亡畫面。","example":"The museum preserved wreckage from an old fishing boat.","example_zh":"博物館保存一艘老漁船的殘骸。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/wreckage-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-undertake-01-v1","level":"senior","word":"undertake","sort_order":1,"sense":"承擔","alt_zh":"高中社團與成年老師在花園入口一起查看修復模型、準備安全工具。","example":"The club agreed to undertake the restoration of the school garden.","example_zh":"社團同意承擔修復校園花園的工作。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/undertake-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-unilateral-01-v1","level":"senior","word":"unilateral","sort_order":1,"sense":"單邊的","alt_zh":"兩位成年專案夥伴在會議桌前，一人獨自移動建築模型、另一人驚訝提出討論，無文字。","example":"The unilateral decision surprised the other partner.","example_zh":"單方面的決定讓另一位合作夥伴驚訝。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/unilateral-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-uranium-01-v1","level":"senior","word":"uranium","sort_order":1,"sense":"鈾","alt_zh":"成年導覽員帶高中訪客從適當距離觀看專業密閉防護櫃內的礦物樣本，無處理或製備資訊。","example":"The museum displayed a uranium mineral inside a sealed protective case.","example_zh":"博物館在密閉防護櫃中展示含鈾礦物。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/uranium-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-utensil-01-v1","level":"senior","word":"utensil","sort_order":1,"sense":"器具","alt_zh":"成年烹飪老師在高中教學廚房展示乾淨木湯匙與整齊烹飪碗。","example":"The wooden spoon was the most useful utensil in the cooking lesson.","example_zh":"木湯匙是烹飪課裡最實用的器具。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/utensil-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-utopia-01-v1","level":"senior","word":"utopia","sort_order":1,"sense":"烏托邦","alt_zh":"高中生閱讀小說，桌上插畫呈現綠樹環繞、各區有小圖書館的理想城鎮。","example":"The novel imagined a utopia where every community had a library.","example_zh":"小說想像每個社區都有圖書館的烏托邦。","image_url":"https://jbspxqebcrkilfcddluo.supabase.co/storage/v1/object/public/word-illustrations/senior/utopia-01-v1.webp","local_path":"","style":"generated-senior-v1","version":1},{"id":"senior-adhere-01-v1","l